module.exports = function (RED) {
    "use strict";

    function EventNode(n) {
        RED.nodes.createNode(this, n);
        let node = this;

        // 配置参数
        this.eventType = n.eventType;

        let newMsg = {};

        // 在节点初始化时自动触发输入事件
        setImmediate(function () {
            node.emit("input", {});
        });

        this.on("input", function (msg, send, done) {
            msg = msg || {};
            msg.type = node.type;
            msg.eventType = node.eventType;  // 使用配置的 eventType

            let nodeId = node.id;
            newMsg[nodeId] = msg;

            send(newMsg);  // 发送消息到下游节点
            done();
        });
    }

    RED.nodes.registerType("Event", EventNode);
}